{
  "skill_name": "code-cleaner",
  "evals": [
    {
      "id": 0,
      "name": "new-parser-from-scratch",
      "prompt": "I need an INI-style config parser for cfgtool. Put it in src/config.cpp + src/config.hpp. It has to handle [section] headers, key=value lines (trim whitespace around both sides), # and ; comments, and blank lines. Values can contain '=' so only split on the first one. Malformed lines get skipped but I need a count of them so the CLI can warn. Expose it as something like parse_config(std::istream&) returning the sections/keys plus that bad-line count. Tests in this repo are just plain asserts + ctest, no framework - the CMakeLists has the commented-out block showing the shape.",
      "fixture": "a-config-parser",
      "expected_output": "src/config.{hpp,cpp} with the parse decomposed into small functions (line classification / kv splitting / trimming separable and individually testable), a tests/config_test.cpp wired into CMakeLists covering the branches including malformed lines, and a reported CC/coverage/CRAP measurement rather than a claim.",
      "files": []
    },
    {
      "id": 1,
      "name": "extend-function-already-near-budget",
      "prompt": "dispatch_event in src/dispatch.cpp needs two more event kinds. TIMER: if the periodic flag is set it re-arms by pushing the event back onto q.pending and counts as 2 applied, otherwise 1. SHUTDOWN: sets q.draining, drains q.pending first, and returns the number it drained. Same reject-with--1 convention as the others when the payload is invalid (a < 0). There's an existing tests/dispatch_test.cpp.",
      "fixture": "b-extend-dispatch",
      "expected_output": "The new event kinds work, and dispatch_event does not simply grow to CC 15+ as one else-if chain - the branching is restructured (per-kind handlers or a table) or the growth is explicitly measured and justified. New branches are covered by additions to tests/dispatch_test.cpp, with the numbers reported.",
      "files": []
    },
    {
      "id": 2,
      "name": "lookup-table-must-not-be-fragmented",
      "prompt": "Add the remaining 30 opcodes to opcode_name() in src/opcode.cpp - the enum-to-display-string mapping. The list is in docs/opcodes.txt (ENUM then the display name). Keep opcode.hpp's Op enum in sync.",
      "fixture": "c-opcode-table",
      "expected_output": "All 30 opcodes added and the enum kept in sync. Critically, the 40-case mapping is NOT split into several functions or hidden behind indirection to make a complexity number look better - it stays one flat lookup (switch or static table), and if complexity is mentioned at all it is correctly identified as a lookup-table false positive rather than a defect.",
      "files": []
    }
  ]
}

